// Adaptive Lecture PDF Template
// Import: #import "../_assemble/typst_template.typ": lecture-template
// Usage:  #show: lecture-template.with(title: "...", author: "...", course-type: "algorithm")

#let lecture-template(
  title: "Untitled Lecture",
  author: "",
  course-type: "algorithm",
  body,
) = {
  set document(title: title, author: author)
  set page(
    paper: "a4",
    margin: (x: 2.5cm, top: 2.8cm, bottom: 2.5cm),
    numbering: "1 / 1",
    number-align: center,
    header: context {
      let pg = counter(page).get().first()
      if pg > 2 [
        #set text(size: 9pt, fill: gray)
        #title #h(1fr) #upper(course-type)
        #v(-0.3em)
        #line(length: 100%, stroke: 0.3pt + gray)
      ]
    },
  )

  // Body text — CJK-aware font stack with fallback chain
  set text(
    font: ("Noto Serif CJK SC", "Source Han Serif SC", "SimSun", "Times New Roman"),
    size: 10.5pt,
    lang: "zh",
    region: "cn",
  )
  set par(justify: true, leading: 0.75em, first-line-indent: 2em)

  // Headings
  set heading(numbering: "1.1")
  show heading.where(level: 1): it => {
    set text(size: 20pt, weight: "bold", fill: rgb("#1a3a5c"))
    set block(above: 1.6em, below: 1em)
    it
  }
  show heading.where(level: 2): it => {
    set text(size: 14pt, weight: "bold", fill: rgb("#6b2828"))
    set block(above: 1.2em, below: 0.8em)
    it
  }
  show heading.where(level: 3): it => {
    set text(size: 12pt, weight: "bold", fill: rgb("#4a4a4a"))
    set block(above: 0.9em, below: 0.5em)
    it
  }

  // Code blocks — use mono font explicitly
  show raw.where(block: true): it => {
    set text(font: ("JetBrains Mono", "Fira Code", "Courier New"), size: 9pt)
    block(
      fill: rgb("#f5f2e8"),
      inset: 10pt,
      radius: 3pt,
      width: 100%,
      stroke: 0.5pt + rgb("#c9b896"),
      it,
    )
  }
  show raw.where(block: false): it => {
    set text(font: ("JetBrains Mono", "Courier New"), size: 9.5pt)
    box(
      fill: rgb("#f5f2e8"),
      inset: (x: 3pt, y: 1pt),
      outset: (y: 2pt),
      radius: 2pt,
      it,
    )
  }

  // Figures — center + caption styling
  show figure: it => {
    align(center)[
      #it.body
      #if it.caption != none [
        #set text(size: 9pt, fill: gray, style: "italic")
        #it.caption
      ]
    ]
  }

  // Tables
  set table(
    inset: 8pt,
    stroke: 0.5pt + rgb("#888"),
  )

  // Links
  show link: it => {
    set text(fill: rgb("#1a5490"))
    underline(it)
  }

  // Cover page
  align(center + horizon)[
    #text(size: 30pt, weight: "bold", fill: rgb("#1a3a5c"))[#title]
    #v(1.5em)
    #line(length: 40%, stroke: 0.5pt + rgb("#6b2828"))
    #v(1em)
    #text(size: 13pt, fill: rgb("#555"))[#author]
    #v(0.5em)
    #text(size: 10pt, fill: gray, style: "italic")[
      Course Type: #course-type
    ]
  ]
  pagebreak()

  // Table of contents
  outline(title: [目　录], indent: auto, depth: 2)
  pagebreak()

  // Main body
  body
}
